  "helpGuides.all": "Todas las guías",
  "helpGuides.content.credits.l1": "Créditos y facturación",
  "helpGuides.content.credits.l2": "Política de reembolso",
  "helpGuides.content.credits.s1.body": "Imágenes, vídeo, audio y voz gastan los mismos créditos. Cada modelo muestra su precio antes de generar.",
  "helpGuides.content.credits.s1.title": "Un saldo para todo",
  "helpGuides.content.credits.s2.body": "Los 10 créditos de registro se gastan primero y caducan 90 días después de concederse si no se usan.",
  "helpGuides.content.credits.s2.title": "Créditos gratis",
  "helpGuides.content.credits.s3.body": "Los paquetes de créditos se compran en la página Créditos a través de Stripe. Los créditos comprados nunca caducan.",
  "helpGuides.content.credits.s3.title": "Comprar créditos",
  "helpGuides.content.credits.s4.body": "Si una generación falla, sus créditos vuelven a tu saldo automáticamente. Biblioteca muestra la generación fallida y su reembolso.",
  "helpGuides.content.credits.s4.title": "Cuando algo falla",
  "helpGuides.content.credits.s5.body": "Una cuenta puede iniciar 10 generaciones por minuto. Si te pasas de ese límite, se rechaza sin cobrarte.",
  "helpGuides.content.credits.s5.title": "Límites",
  "helpGuides.content.credits.summary": "Un solo saldo, precios por adelantado y reembolsos automáticos.",
  "helpGuides.content.credits.title": "Cómo funcionan los créditos y los reembolsos",
  "helpGuides.content.first-generation.l1": "Abrir el estudio",
  "helpGuides.content.first-generation.l2": "Ver todos los precios",
  "helpGuides.content.first-generation.s1.body": "Ve a Crear. Primero inicia sesión (Iniciar sesión) o crea una cuenta; las cuentas nuevas reciben 10 créditos gratis una vez confirmado el correo.",
  "helpGuides.content.first-generation.s1.title": "Abrir el estudio",
  "helpGuides.content.first-generation.s2.body": "La lista de la derecha muestra cada modelo con su precio en créditos. Los modelos de imagen, vídeo y audio gastan del mismo saldo.",
  "helpGuides.content.first-generation.s2.title": "Elige un modelo",
  "helpGuides.content.first-generation.s3.body": "Describe lo que quieres ver. Para un vídeo, indica qué se mueve y cómo se mueve la cámara.",
  "helpGuides.content.first-generation.s3.title": "Escribe el prompt",
  "helpGuides.content.first-generation.s4.body": "El total aparece sobre el botón Generar antes de pulsarlo. Un clip de 10 s cuesta el doble que uno de 5 s, y si eliges más de una imagen el precio se multiplica por la cantidad.",
  "helpGuides.content.first-generation.s4.title": "Comprueba el coste",
  "helpGuides.content.first-generation.s5.body": "Los créditos se descuentan al pulsar Generar. Si la generación falla, vuelven a tu saldo automáticamente.",
  "helpGuides.content.first-generation.s5.title": "Generar",
  "helpGuides.content.first-generation.summary": "Elige un modelo, mira el precio y genera.",
  "helpGuides.content.first-generation.title": "Crea tu primera imagen o vídeo",
  "helpGuides.content.library.l1": "Abrir Biblioteca",
  "helpGuides.content.library.s1.body": "Aparecen todas las generaciones, incluidas las fallidas, para que veas qué se reembolsó.",
  "helpGuides.content.library.s1.title": "Abrir Biblioteca",
  "helpGuides.content.library.s2.body": "Filtra por estado y por tipo (imágenes, vídeo, audio) y alterna entre cuadrícula y lista.",
  "helpGuides.content.library.s2.title": "Filtra",
  "helpGuides.content.library.s3.body": "La estrella de una tarjeta la añade a Favourites. Los favoritos se recuerdan en el navegador donde los marcaste.",
  "helpGuides.content.library.s3.title": "Marca tus favoritos con estrella",
  "helpGuides.content.library.s4.body": "Los archivos generados no se guardan para siempre. Cada tarjeta indica cuánto tiempo se conserva su archivo; descarga lo que necesites antes de que pase ese plazo.",
  "helpGuides.content.library.s4.title": "Descarga lo que quieras conservar",
  "helpGuides.content.library.summary": "Filtra, marca con estrella y descarga desde tu Biblioteca.",
  "helpGuides.content.library.title": "Encuentra y conserva lo que creaste",
  "helpGuides.content.templates.l1": "Explorar plantillas",
  "helpGuides.content.templates.s1.body": "Filtra por categoría. Cada tarjeta muestra el modelo con el que funciona y su precio.",
  "helpGuides.content.templates.s1.title": "Explora las plantillas",
  "helpGuides.content.templates.s2.body": "La página de la plantilla muestra el prompt completo, el coste y, si el modelo lo necesita, qué tienes que subir.",
  "helpGuides.content.templates.s2.title": "Abre una",
  "helpGuides.content.templates.s3.body": "Usar esta plantilla abre el estudio con el prompt, el modelo y la proporción ya rellenados. No se cobra nada hasta que pulses Generar.",
  "helpGuides.content.templates.s3.title": "Úsala",
  "helpGuides.content.templates.s4.body": "Edita el prompt antes de generar. La plantilla es un punto de partida, no una receta fija.",
  "helpGuides.content.templates.s4.title": "Hazla tuya",
  "helpGuides.content.templates.summary": "Un prompt, un modelo y una proporción listos con un clic.",
  "helpGuides.content.templates.title": "Empieza desde una plantilla",
  "helpGuides.content.your-own-files.l1": "Ver las herramientas",
  "helpGuides.content.your-own-files.l2": "Uso aceptable",
  "helpGuides.content.your-own-files.s1.body": "La página Tools lista todos los modelos que parten de tu propio archivo, qué necesitan y cuánto cuestan.",
  "helpGuides.content.your-own-files.s1.title": "Elige una herramienta",
  "helpGuides.content.your-own-files.s2.body": "Las imágenes pueden ser PNG, JPEG o WebP de hasta 20 MB. El vídeo es MP4 de hasta 100 MB. La voz es MP3 o WAV de hasta 20 MB.",
  "helpGuides.content.your-own-files.s2.title": "Añade tu archivo",
  "helpGuides.content.your-own-files.s3.body": "En el caso de una imagen, From library te permite elegir una que ya generaste en lugar de subirla otra vez.",
  "helpGuides.content.your-own-files.s3.title": "O reutiliza un resultado",
  "helpGuides.content.your-own-files.s4.body": "Marca la casilla que declara que el archivo es tuyo o que tienes el permiso de todas las personas identificables en él. La declaración queda registrada junto con la generación.",
  "helpGuides.content.your-own-files.s4.title": "Confirma que puedes usarlo",
  "helpGuides.content.your-own-files.s5.body": "El precio y el reembolso en caso de fallo funcionan igual que en cualquier otra generación.",
  "helpGuides.content.your-own-files.s5.title": "Generar",
  "helpGuides.content.your-own-files.summary": "Mejora la resolución, recorta, amplía, edita, anima o sincroniza labios en un archivo que ya tienes.",
  "helpGuides.content.your-own-files.title": "Trabaja con tu propia imagen o vídeo",
